mapper.select:
select * from (
    select

    from t_glue_collect_plan tgcp
    where tgcp.del_flag = '0'
    and tgcp.plan_date = #{planDate}
    and tgcp.factory = #{factory}
    and INSTR(tgcp.glue, #{glue}) > 0
    and tgcp.mix_area = #{mixArea}
    and tgcp.machine_code = #{machineCode}
) t

    order by create_time desc


    order by ${orderStr}

mapper.insert:
insert into t_glue_collect_plan
(id,demand_batch_no,batch_no,plan_date,factory,glue,mix_area,machine_code,total_plan_qty,mid_plan_qty,mid_remark,night_plan_qty,night_remark,day_plan_qty,day_remark,data_source,remark,del_flag,create_by,create_time,update_by,update_time
)
select NULL id, x.*
from (

    select
    #{glueCollectPlan.demandBatchNo,jdbcType= VARCHAR} demand_batch_no,
    #{glueCollectPlan.batchNo,jdbcType= VARCHAR} batch_no, #{glueCollectPlan.planDate,jdbcType=DATE} plan_date,
    #{glueCollectPlan.factory,jdbcType= VARCHAR} factory, #{glueCollectPlan.glue,jdbcType= VARCHAR} glue,
    #{glueCollectPlan.mixArea,jdbcType= VARCHAR} mix_area, #{glueCollectPlan.machineCode,jdbcType= VARCHAR}
    machine_code, #{glueCollectPlan.totalPlanQty,jdbcType=DOUBLE} total_plan_qty,
    #{glueCollectPlan.midPlanQty,jdbcType=DOUBLE} mid_plan_qty, #{glueCollectPlan.midRemark,jdbcType= VARCHAR}
    mid_remark, #{glueCollectPlan.nightPlanQty,jdbcType=DOUBLE} night_plan_qty,
    #{glueCollectPlan.nightRemark,jdbcType= VARCHAR} night_remark, #{glueCollectPlan.dayPlanQty,jdbcType=DOUBLE}
    day_plan_qty, #{glueCollectPlan.dayRemark,jdbcType= VARCHAR} day_remark,
    #{glueCollectPlan.dataSource,jdbcType= VARCHAR} data_source, #{glueCollectPlan.remark,jdbcType= VARCHAR}
    remark, #{glueCollectPlan.delFlag,jdbcType= VARCHAR} del_flag, #{glueCollectPlan.createBy,jdbcType= VARCHAR}
    create_by, #{glueCollectPlan.createTime,jdbcType=DATE} create_time,
    #{glueCollectPlan.updateBy,jdbcType= VARCHAR} update_by, #{glueCollectPlan.updateTime,jdbcType=DATE}
    update_time from dual

) x
